import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class JwtDemo {
    static final String HEADER = Base64.getUrlEncoder().withoutPadding()
        .encodeToString("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes());

    static String base64url(String s) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes());
    }

    static String hmac(String data, String secret) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(secret.getBytes(), "HmacSHA256"));
        return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(data.getBytes()));
    }

    static String sign(String payload, String secret) throws Exception {
        String headerAndPayload = HEADER + "." + base64url(payload);
        return headerAndPayload + "." + hmac(headerAndPayload, secret);
    }

    static boolean verify(String token, String secret) throws Exception {
        String[] parts = token.split("\\.");
        if (parts.length != 3) return false;
        String expected = hmac(parts[0] + "." + parts[1], secret);
        return expected.equals(parts[2]);
    }

    public static void main(String[] args) throws Exception {
        String secret = "my-super-secret-key";
        String payload = "{\"sub\":\"user-1\",\"role\":\"MAGE\"}";
        String token = sign(payload, secret);
        System.out.println("Token: " + token);
        System.out.println("Valid: " + verify(token, secret));
        String tampered = token.split("\\.")[0] + "." +
            base64url("{\"sub\":\"user-1\",\"role\":\"ADMIN\"}") + "." +
            token.split("\\.")[2];
        System.out.println("Tampered valid: " + verify(tampered, secret));
    }
}

