import java.util.*;

public class AuthZDemo {
    record Resource(String id, String ownerId, String content) {}

    static class ResourceService {
        Map<String, Resource> store = new HashMap<>();
        void add(Resource r) { store.put(r.id(), r); }

        Resource getInsecure(String id) {
            return store.get(id);
        }

        Resource getSecure(String id, String requestingUserId) {
            Resource r = store.get(id);
            if (r == null) throw new NoSuchElementException("Not found");
            if (!r.ownerId().equals(requestingUserId)) {
                throw new SecurityException("Forbidden");
            }
            return r;
        }
    }

    public static void main(String[] args) {
        ResourceService svc = new ResourceService();
        svc.add(new Resource("res-1", "alice", "alice-data"));
        svc.add(new Resource("res-2", "bob", "bob-data"));

        // IDOR — charlie accesses alice's data
        Resource r = svc.getInsecure("res-1");
        System.out.println("insecure: " + r.content());

        // Secure — ownership enforced
        try {
            svc.getSecure("res-1", "charlie");
        } catch (SecurityException e) {
            System.out.println("getSecure threw: " + e.getMessage());
        }

        // Alice can access her own resource
        System.out.println("alice getSecure: " + svc.getSecure("res-1", "alice").content());
    }
}
